project-profile.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.profile {
  max-width: 620px;
}

.profile-intro {
  padding-block: 20px;
  padding-inline: 20px;
  background: rgb(226 241 235);
  border-radius: 8px;
}

.profile-intro p {
  margin: 0 0 8px;
}

.profile-content > * {
  padding: 12px 4px;
}

.profile-content h2 {
  margin: 0;
  font-size: 18px;
}

project-login.script.js:
const form = document.querySelector('#login-form');
const usernameField = document.querySelector('#login-name');
const passwordField = document.querySelector('#login-password');
const loginStatus = document.querySelector('#login-status');

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const username = usernameField.value.trim();
  const password = passwordField.value;

  if (username === '' || password === '') {
    loginStatus.textContent = 'Please fill in your account number and password.';
    return;
  }

  const matched = username === 'learner' && password === 'study123';
  loginStatus.textContent = matched ? 'Login successful.' : 'The account number or password is incorrect.';
});

project-calculator.style.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px 14px; background: #edf5f2; color: #243447; font: 16px/1.6 system-ui, sans-serif; }
.sheet { max-width: 760px; margin: 0 auto; padding: 20px; border-radius: 12px; background: white; }
h1 { margin: 0 0 .5em; font-size: 1.5rem; line-height: 1.3; }
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; height: auto; }
a { color: #125a46; }

.calculator {
  max-width: 420px;
}

.number-fields, .operations {
  margin-bottom: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.field input {
  width: 100%;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid #a3afb9;
  border-radius: 6px;
}

.operations button {
  display: block;
  padding: 6px 12px;
  border: 0;
  border-radius: 6px;
  color: white;
  background-color: #125a46;
}

.result {
  margin: 12px 0 0;
  padding: 8px 12px;
  border-radius: 6px;
  background-color: #edf5f2;
}

#calc-result {
  margin-inline-start: 8px;
  font-weight: 700;
}

/* Set the two-column layout of the input group and button group here. */

.number-fields, .operations {
  display: flex;
  gap: 12px;
}

.number-fields > *, .operations > * {
  flex: 1;
  min-width: 0;
}
